import { useEffect, useState } from "react";
//#region src/useObjectUrl/index.ts
const useObjectUrl = (object) => {
	const [url, setUrl] = useState();
	useEffect(() => {
		if (!object) {
			setUrl(void 0);
			return;
		}
		const objectUrl = URL.createObjectURL(object);
		setUrl(objectUrl);
		return () => {
			URL.revokeObjectURL(objectUrl);
		};
	}, [object]);
	return url;
};
//#endregion
export { useObjectUrl };
